import React, { useState } from "react";
import PencilIcon from "../assets/Pencil.png";
import CursorIcon from "../assets/Cursor.png";
import ChainIcon from "../assets/chain.png";
import HappyLogo from "../assets/HappyLogo.png";
import AnswerBubble from "../assets/Answer.png";
import LightbulbIcon from "../assets/Lightbulb.png";
import ChatCircleDots from "../assets/ChatCircleDots.png";
import BusIcon from "../assets/Bus2.png";
import LightningIcon from "../assets/Lightning.png";
import BlackCircle from "../assets/blackcircle.png";
import HealthIcon from "../assets/Health2.png";
import SparkleIcon from "../assets/sparkle.png";
import styles from "./AnswerBox.module.css";

export default function AnswerBox() {
  const [tab, setTab] = useState("answer");
  const [searchResult, setSearchResult] = useState(null);
  const [input, setInput] = useState("");

  // 검색 실행시 예시 데이터 set
  const handleSearch = () => {
    setSearchResult({
      answer: (
        <>
          서산시의 노인 복지에 대한 주요 내용은 다음과 같아요.
          <ul>
            <li>
              <b>주요 복지 정책 및 사업</b>
              <ul>
                <li>
                  <b>노인여가복지시설 지원:</b> 서산시는 경로당, 마을회관 등 관내 440개의 노인여가복지시설을 대상으로 냉난방비와 각종 물품을 지원하고 있습니다.
                </li>
                <li>
                  <b>노인 일자리 사업:</b> 어르신들의 경제적 안정과 사회 참여를 돕기 위해 노인 일자리를 제공하고 있습니다.
                </li>
              </ul>
            </li>
            <li>
              <b>주요 복지 시설</b>
              <ul>
                <li>
                  <b>서산노인복지센터:</b> 지곡면에 위치한 시설로, 노인 장기요양보험 관련 서비스를 제공합니다.
                </li>
                <li>
                  <b>서산탑노인복지센터:</b> 음암면에 위치한 요양시설입니다.
                </li>
                <li>
                  <b>우리들주야간노인복지센터:</b> 수석동에 위치하며, 방문목욕, 방문요양, 주야간 보호 등 다양한 재가노인복지 서비스를 제공합니다.
                </li>
              </ul>
            </li>
          </ul>
        </>
      ),
      sources: [
        {
          title: "충청남도 서산시_재가노인 복지시설",
          link: "https://data.chungnam.go.kr",
          provider: "충청남도 데이터포털"
        }
      ]
    });
    setTab("answer");
  };

  // 검색창 Enter 키 지원
  const handleInputKeyDown = e => {
    if (e.key === "Enter") handleSearch();
  };

  // 결과 닫기 (테스트용)
  const handleClose = () => setSearchResult(null);

  return (
    <div className="answer-box">
      {/* [1] 상단 검색 입력/버튼 예시 (실제 프로젝트에서 필요시 위치 조정) */}
      <div style={{ width: "100%", display: "flex", justifyContent: "center", margin: "36px 0 16px 0" }}>
        <input
          style={{ width: 320, fontSize: 18, borderRadius: 12, border: "1px solid #dadada", padding: "8px 18px" }}
          value={input}
          onChange={e => setInput(e.target.value)}
          onKeyDown={handleInputKeyDown}
          placeholder="검색어 입력 후 엔터 또는 버튼"
        />
        <button
          onClick={handleSearch}
          style={{
            marginLeft: 12, fontSize: 17, fontWeight: 600, color: "#fff",
            background: "#11aab2", border: 0, borderRadius: 10, padding: "8px 24px", cursor: "pointer"
          }}
        >검색</button>
        {searchResult && (
          <button onClick={handleClose} style={{ marginLeft: 8, color: "#888", fontWeight: 500, background: "#f0f0f0", border: 0, borderRadius: 9, padding: "8px 16px", cursor: "pointer" }}>
            결과 닫기
          </button>
        )}
      </div>

      {/* [2] 검색 결과 있을 때: 카드형 답변 */}
      {searchResult && (
        <div className={styles.bgFinal}>
          <div className={styles.cardWrap}>
            <div className={styles.resultHeader}>
              <img src={HappyLogo} className={styles.resultLogo} alt="" />
              <div className={styles.bubbleBox}>
                <div className={styles.bubbleText}>
                  AI 답변이 완료되었습니다
                  <img src={SparkleIcon} className={styles.sparkleIcon} alt="" />
                </div>
                <img src={AnswerBubble} className={styles.bubbleImg} alt="" />
              </div>
            </div>
            {/* 탭 */}
            <div className={styles.tabs}>
              <button
                className={`${styles.tabBtn} ${tab === "answer" ? styles.active : ""}`}
                onClick={() => setTab("answer")}
                type="button"
              >
                답변
              </button>
              <button
                className={`${styles.tabBtn} ${tab === "source" ? styles.active : ""}`}
                onClick={() => setTab("source")}
                type="button"
              >
                출처
              </button>
            </div>
            {/* 내용 */}
            <div className={styles.tabContent}>
              {tab === "answer" && (
                <div className={styles.answerMain}>
                  {searchResult.answer}
                </div>
              )}
              {tab === "source" && (
                <div>
                  <div className={styles.sourceGuide}>답변에 사용된 출처를 알려드릴게요.</div>
                  {searchResult.sources.map((item, idx) => (
                    <div className={styles.sourceCard} key={idx}>
                      <div className={styles.sourceNum}>{idx + 1}</div>
                      <div className={styles.sourceBody}>
                        <div className={styles.sourceTitleRow}>
                          <b className={styles.sourceTitle}>{item.title}</b>
                          <a href={item.link} target="_blank" rel="noopener noreferrer" className={styles.sourceLinkIcon}>
                            <img src={ChainIcon} alt="링크" />
                          </a>
                        </div>
                        <div className={styles.sourceMeta}>
                          <img src={PencilIcon} alt="" />
                          {item.provider}
                        </div>
                        <div className={styles.sourceMeta}>
                          <img src={CursorIcon} alt="" />
                          <span className={styles.sourceUrlText}>{item.link}</span>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* [3] 검색 결과 없을 때: 인기질문/카테고리 */}
      {!searchResult && (
        <div className={styles.contentsWrap}>
          {/* 인기질문 */}
          <div className={styles.section}>
            <div className={styles.sectionTitle}>
              <img src={LightbulbIcon} alt="" className={styles.titleIcon} />
              인기 질문
            </div>
            <div className={styles.grid}>
              {[
                { tag: "민원", text: "서산시청 민원 어떻게 넣어요?" },
                { tag: "민원", text: "서산시청 민원 어떻게 넣어요?" },
                { tag: "행사", text: "오늘 서산에 열리는 행사 뭐 있어?" },
                { tag: "행사", text: "오늘 서산에 열리는 행사 뭐 있어?" },
              ].map((q, i) => (
                <div key={i} className={styles.card}>
                  <div className={styles.cardTop}>
                    <span className={styles.tag}>{q.tag}</span>
                    <img src={ChatCircleDots} alt="" className={styles.cardIcon} />
                  </div>
                  <div className={styles.cardText}>{q.text}</div>
                </div>
              ))}
            </div>
          </div>
          {/* 인기카테고리 */}
          <div className={styles.section}>
            <div className={styles.sectionTitle}>
              <img src={LightningIcon} alt="" className={styles.titleIcon} />
              인기 카테고리
            </div>
            <div className={styles.gridCat}>
              <div className={styles.catCard}>
                <div>
                  <div className={styles.catTitle}>교통</div>
                  <div className={styles.catDesc}>
                    복잡한 서산시의 교통 노선,<br />바로 알아보세요
                  </div>
                </div>
                <img src={BusIcon} alt="교통" className={styles.catImg} />
                <img src={BlackCircle} alt="arrow" className={styles.arrowIcon} />
              </div>
              <div className={styles.catCard}>
                <div>
                  <div className={styles.catTitle}>복지</div>
                  <div className={styles.catDesc}>
                    복지혜택, 찾기 힘드신가요?<br />통합 정보를 확인하세요
                  </div>
                </div>
                <img src={HealthIcon} alt="복지" className={styles.catImg} />
                <img src={BlackCircle} alt="arrow" className={styles.arrowIcon} />
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
